# Expected values generated by test/scipy/gen_linalg2_expected.py (scipy 1.18.1).
import numpy as np
import scipy.linalg as sl
import linalg_matfuncs_expected as X

def close(x, ref, rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    a = np.asarray(x).ravel()
    if a.shape[0] != len(ref):
        print('size', a.shape[0], len(ref))
        return False
    ok = True
    for i in range(len(ref)):
        u = a[i]
        v = ref[i]
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', i, u, v)
            ok = False
    return ok

M = np.array([[1., .5, .2], [.1, 2., .3], [.4, .2, 1.5]])
N = np.array([[0., 1.], [-2., -3.]])
Mc = np.array([[1. + 1j, .5 + 0j, 0j], [1j * .1, 2. + 0j, .3 + 0j], [.4 + 0j, .2 - .5j, 1.5 + 0j]])

class Sq:
    def __call__(self, x):
        return x * x + 1.0

class Ex:
    def __call__(self, x):
        return np.exp(x)

@test
def test_trig_hyp():
    assert close(sl.cosm(M), X.cosm)
    assert close(sl.sinm(M), X.sinm)
    assert close(sl.tanm(M), X.tanm)
    assert close(sl.coshm(M), X.coshm)
    assert close(sl.sinhm(M), X.sinhm)
    assert close(sl.tanhm(M), X.tanhm)
    assert close(sl.cosm(Mc), X.cosmc)
    assert close(sl.sinhm(Mc), X.sinhmc)
test_trig_hyp()

@test
def test_funm_signm():
    assert close(sl.funm(M, Sq()), X.funm, 1e-9, 1e-11)
    assert close(sl.funm(N, Ex()), X.funmexp, 1e-9, 1e-11)
    assert close(sl.signm(np.array([[2., 1., 0.], [0., -3., 1.], [0., 0., 1.]])), X.signm, 1e-9, 1e-11)
    assert close(sl.signm(np.array([[1., 2.], [3., -4.]])), X.signm2, 1e-9, 1e-11)
test_funm_signm()

@test
def test_frechet():
    E = np.array([[0., 0., .1], [0., 0., .1], [-.2, -.2, -.3]])
    R, L = sl.expm_frechet(M, E)
    assert close(R, X.frR)
    assert close(L, X.frL)
    R, L = sl.expm_frechet(4 * M, np.eye(3))
    assert close(R, X.frR2)
    assert close(L, X.frL2)
    assert close(sl.expm_frechet(M, np.ones((3, 3)), method='blockEnlarge', compute_expm=False), X.frBE)
    assert close([sl.expm_cond(M)], X.econd, 1e-9)
test_frechet()

@test
def test_expm_sqrtm_logm():
    assert close(sl.expm(10 * M), X.expm)
    assert close(sl.expm(N), X.expmN)
    assert close(sl.sqrtm(M), X.sqrtm)
    assert close(sl.logm(M), X.logm)
    assert close(sl.fractional_matrix_power(M, 0.3), X.fmp)
    assert close(sl.fractional_matrix_power(M, -1.5), X.fmp2)
    assert close(sl.sqrtm(Mc), X.sqrtmc)
    assert close(sl.logm(Mc), X.logmc)
    assert close(sl.expm(np.array([[1., 2., 3.], [0., -1., 4.], [0., 0., 3.]]) * 3), X.expmup)
test_expm_sqrtm_logm()
